import{_ as s,o as n,c as t,aN as m}from"./chunks/framework.D31DlcCL.js";const l="/img/math-age-2.svg",g=JSON.parse('{"title":"小学奥数进阶：年龄问题的三大法则","description":"年龄问题不仅考察计算，更考察对“时间流逝”的理解。本文总结了年龄差不变、倍数变化等核心规律，带你玩转年龄题。","frontmatter":{"title":"小学奥数进阶：年龄问题的三大法则","date":"2026-02-08T11:10:00.000Z","categories":["数学"],"tags":["小学数学","奥数","年龄问题"],"description":"年龄问题不仅考察计算，更考察对“时间流逝”的理解。本文总结了年龄差不变、倍数变化等核心规律，带你玩转年龄题。","cover":"/img/math-age-2.svg","top_img":"/img/banner.svg","toc_number":true,"katex":true},"headers":[],"relativePath":"posts/primary-math-olympiad-age-2.md","filePath":"posts/primary-math-olympiad-age-2.md","lastUpdated":null}'),o={name:"posts/primary-math-olympiad-age-2.md"};function r(e,a,p,i,c,h){return n(),t("div",null,[...a[0]||(a[0]=[m('<h1 id="小学奥数进阶-年龄问题的三大法则" tabindex="-1">小学奥数进阶：年龄问题的三大法则 <a class="header-anchor" href="#小学奥数进阶-年龄问题的三大法则" aria-label="Permalink to &quot;小学奥数进阶：年龄问题的三大法则&quot;">​</a></h1><h2 id="一、-三大核心法则" tabindex="-1">一、 三大核心法则 <a class="header-anchor" href="#一、-三大核心法则" aria-label="Permalink to &quot;一、 三大核心法则&quot;">​</a></h2><p>年龄问题之所以特殊，是因为它遵循以下三个铁律：</p><ol><li><strong>年龄差永远不变</strong>：你今年比我大 5 岁，10 年后、100 年后依然比我大 5 岁。</li><li><strong>年龄增长是同步的</strong>：时间过去 1 年，每个人都增加 1 岁。</li><li><strong>倍数关系会改变</strong>：随着年龄增长，大年龄与小年龄的倍数关系会逐渐缩小。</li></ol><hr><h2 id="二、-核心模型-转化为-差倍问题" tabindex="-1">二、 核心模型：转化为“差倍问题” <a class="header-anchor" href="#二、-核心模型-转化为-差倍问题" aria-label="Permalink to &quot;二、 核心模型：转化为“差倍问题”&quot;">​</a></h2><p>由于“年龄差”是不变量，所以绝大多数年龄问题最终都会转化为<strong>差倍问题</strong>。</p><h3 id="_1-寻找当年的倍数" tabindex="-1">1. 寻找当年的倍数 <a class="header-anchor" href="#_1-寻找当年的倍数" aria-label="Permalink to &quot;1. 寻找当年的倍数&quot;">​</a></h3><p><strong>例题</strong>：爸爸今年 35 岁，儿子今年 7 岁。几年后爸爸的年龄是儿子的 3 倍？</p><ul><li><strong>第一步：找差</strong>：年龄差 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>3</mn><mn>5</mn><mo>−</mo><mn>7</mn><mo>=</mo><mn>2</mn><mn>8</mn></mrow><annotation encoding="application/x-tex">= 35 - 7 = 28</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">7</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">8</span></span></span></span> 岁（永远不变）。</li><li><strong>第二步：找目标倍数</strong>：目标是 3 倍。</li><li><strong>第三步：求目标年龄</strong>： <ul><li>此时，儿子是 1 份，爸爸是 3 份。</li><li>份数差 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>3</mn><mo>−</mo><mn>1</mn><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">= 3 - 1 = 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">2</span></span></span></span> 份。</li><li>2 份对应的正是 28 岁。</li><li><strong>儿子目标年龄</strong> <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>2</mn><mn>8</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">= 28 \\div 2 = 14</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">8</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span></span></span></span> 岁。</li></ul></li><li><strong>第四步：算年数</strong>：儿子从 7 岁到 14 岁，经过了 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>4</mn><mo>−</mo><mn>7</mn><mo>=</mo><mn>7</mn></mrow><annotation encoding="application/x-tex">14 - 7 = 7</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">4</span><span class="mbin">−</span><span class="mord mathrm">7</span><span class="mrel">=</span><span class="mord mathrm">7</span></span></span></span> 年。</li><li><strong>结论</strong>：7 年后。</li></ul><p><img src="'+l+'" alt="年龄问题进阶图解"></p><hr><h2 id="三、-进阶变式-复杂的描述" tabindex="-1">三、 进阶变式：复杂的描述 <a class="header-anchor" href="#三、-进阶变式-复杂的描述" aria-label="Permalink to &quot;三、 进阶变式：复杂的描述&quot;">​</a></h2><h3 id="_1-过去-与-未来-的穿越" tabindex="-1">1. “过去”与“未来”的穿越 <a class="header-anchor" href="#_1-过去-与-未来-的穿越" aria-label="Permalink to &quot;1. “过去”与“未来”的穿越&quot;">​</a></h3><p><strong>例题</strong>：当甲像乙现在这么大时，乙 2 岁；当乙像甲现在这么大时，甲 20 岁。求甲乙现在各几岁？</p><ul><li><strong>分析</strong>：这道题看似绕口，其实关键还是“差不变”。</li><li><strong>画图思维</strong>： <ul><li>乙(过去) \\xrightarrow{+差} 乙(现在) \\xrightarrow{+差} 乙(未来)</li><li>对应的甲：</li><li>甲(过去) \\xrightarrow{+差} 甲(现在) \\xrightarrow{+差} 甲(未来)</li></ul></li><li><strong>关键点</strong>：题目中的“甲像乙现在这么大”和“乙像甲现在这么大”，实际上是时间轴上的两个等距点。</li><li><strong>计算</strong>： <ul><li>2 岁到 20 岁之间包含了 3 个年龄差。</li><li>年龄差 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mo>(</mo><mn>2</mn><mn>0</mn><mo>−</mo><mn>2</mn><mo>)</mo><mo>÷</mo><mn>3</mn><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">= (20 - 2) \\div 3 = 6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mopen">(</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">6</span></span></span></span> 岁。</li><li>乙(现在) <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>2</mn><mo>+</mo><mn>6</mn><mo>=</mo><mn>8</mn></mrow><annotation encoding="application/x-tex">= 2 + 6 = 8</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">8</span></span></span></span> 岁。</li><li>甲(现在) <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>8</mn><mo>+</mo><mn>6</mn><mo>=</mo><mn>1</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">= 8 + 6 = 14</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">8</span><span class="mbin">+</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span></span></span></span> 岁。</li></ul></li></ul><hr><h2 id="四、-解题金钥匙" tabindex="-1">四、 解题金钥匙 <a class="header-anchor" href="#四、-解题金钥匙" aria-label="Permalink to &quot;四、 解题金钥匙&quot;">​</a></h2><ol><li><strong>锁定差</strong>：第一步永远是算年龄差。</li><li><strong>画表格</strong>：对应好“过去”、“现在”、“将来”三个时间点。</li><li><strong>找倍数</strong>：利用差倍公式求出其中一人的目标年龄。</li></ol><hr><h2 id="五、-举一反三-练习题" tabindex="-1">五、 举一反三（练习题） <a class="header-anchor" href="#五、-举一反三-练习题" aria-label="Permalink to &quot;五、 举一反三（练习题）&quot;">​</a></h2><ol><li>兄弟俩今年的年龄和是 30 岁。当哥哥像弟弟现在这么大时，弟弟的年龄恰好是哥哥现在年龄的一半。求兄弟俩各几岁？</li><li>妈妈今年 32 岁，女儿今年 4 岁。几年后妈妈的年龄是女儿的 5 倍？</li></ol><hr><p><em>记住：时间在走，但差距不减！</em></p>',24)])])}const u=s(o,[["render",r]]);export{g as __pageData,u as default};
